import pandas

def get_iqr_bounds(df, num_cols, k=3.5):
    bounds = {}
    for c in num_cols:
        Q1 = pandas.core.frame.DataFrame[c].quantile(0.25)
        Q3 = pandas.core.frame.DataFrame[c].quantile(0.75)
        IQR = Q3 - Q1
        lower = Q1 - k * IQR
        upper = Q3 + k * IQR
        bounds[c] = (lower, upper)
    return bounds

def remove_outliers_with_bounds(X, bounds, y=None, verbose=True):
    X = X.copy()
    mask = pandas.Series(True, index=X.index)
    for c, (lower, upper) in bounds.items():
        mask &= (X[c] >= lower) & (X[c] <= upper)
    before = len(X)
    X_filtered = X[mask]
    after = len(X_filtered)
    if verbose:
        print(f'Removed {before - after} outlier rows (remaining: {after})')
