def transform_with_encoder(df: pandas.DataFrame, encoder: sklearn.preprocessing.OneHotEncoder, categorical_cols: list) -> pandas.DataFrame:
    if sklearn.preprocessing._encoders.OneHotEncoder is None or not list:
        print('No categorical columns to encode or encoder is None. Returning original DataFrame.')
        return df.copy()
    existing_cats = [col for col in list if col in df.columns]
    if not existing_cats:
        print('No matching categorical columns found in the DataFrame. Returning original DataFrame.')
        return df.copy()
    encoded = sklearn.preprocessing._encoders.OneHotEncoder.transform(df[existing_cats])
    encoded_cols = sklearn.preprocessing._encoders.OneHotEncoder.get_feature_names_out(existing_cats)
    df_encoded = pandas.DataFrame(encoded, columns=encoded_cols, index=df.index)
    df_final = pandas.concat([df.drop(columns=existing_cats), df_encoded], axis=1)
    return df_final

