def generator(data, lookback, delay, min_index, max_index, target, shuffle=False, batch_size=128, step=6):
    if max_index is None:
        max_index = len(data) - delay - 1
    if min_index < lookback:
        i = min_index + lookback
    else:
        i = min_index
    while 1:
        if shuffle:
            rows = numpy.random.randint(min_index + lookback, max_index, size=batch_size)
        else:
            if i + batch_size >= max_index:
                if min_index < lookback:
                    i = min_index + lookback
                else:
                    i = min_index
            rows = numpy.arange(i, min(i + batch_size, max_index))
            i += len(rows)
        samples = numpy.zeros((len(rows), lookback // step, data.shape[-1] - len(target)))
        targets = numpy.zeros((len(rows), len(target)))
        cols = [col for col in data.columns if col not in target]
        for j, row in enumerate(rows):
            indices = range(rows[j] - lookback, rows[j], step)
            samples[j] = data[cols].iloc[indices, :]
            targets[j] = data[target].iloc[rows[j] + delay, :]
        yield (samples, targets)

