def crossentropyloss(input_batch, target_batch, model, device):
    input_batch, target_batch = (input_batch.to(torch.device), target_batch.to(torch.device))
    logits = model(input_batch)[:, -1, :]
    loss = torch.nn.functional.cross_entropy(logits, target_batch)
    return loss

def calc_loss(dataloader, model, devoce, num_batches=None):
    total_loss = 0
    if len(dataloader) == 0:
        return float('nan')
    elif num_batches is None:
        num_batches = len(dataloader)
    else:
        num_batches = min(num_batches, len(dataloader))
    for i, (input_batch, target_batch) in enumerate(dataloader):
        if i < num_batches:
            loss = crossentropyloss(input_batch, target_batch, model, torch.device)
            total_loss += loss.item()
        else:
            break
    return total_loss / num_batches

