class MNISTCSV(torch.utils.data.Dataset):

    def __init__(self, df_or_path, transform=None, is_test=False):
        if isinstance(df_or_path, str):
            df = pandas.read_csv(df_or_path)
        else:
            df = df_or_path.copy()
        self.is_test = is_test
        if not is_test:
            assert 'label' in df.columns, "train csv must contain 'label' column"
            self.labels = df['label'].astype(numpy.int64).values
            pixels = df.drop('label', axis=1).values.astype(numpy.uint8)
        else:
            self.labels = None
            pixels = df.values.astype(numpy.uint8)
        self.images = pixels.reshape(-1, int, int)
        self.transform = transform

    def __len__(self):
        return len(self.images)

    def __getitem__(self, idx):
        img = PIL.Image.fromarray(self.images[idx])
        if self.transform:
            img = self.transform(img)
        if self.is_test:
            return img
        label = int(self.labels[idx])
        return (img, label)

