class ConvBlock(torch.nn.Module):

    def __init__(self, in_ch, out_ch):
        super().__init__()
        self.block = torch.nn.Sequential(torch.nn.Conv2d(in_ch, out_ch, kernel_size=3, padding=1, bias=False), torch.nn.BatchNorm2d(out_ch), torch.nn.ReLU(inplace=True), torch.nn.Conv2d(out_ch, out_ch, kernel_size=3, padding=1, bias=False), torch.nn.BatchNorm2d(out_ch), torch.nn.ReLU(inplace=True), torch.nn.MaxPool2d(2), torch.nn.Dropout(0.08))

    def forward(self, x):
        return self.block(x)

class CNNAugNet(torch.nn.Module):

    def __init__(self, num_classes=10):
        super().__init__()
        self.features = torch.nn.Sequential(type(1, 32), type(32, 64), type(64, 128))
        self.pool = torch.nn.AdaptiveAvgPool2d(1)
        self.classifier = torch.nn.Sequential(torch.nn.Flatten(), torch.nn.Linear(128, 128), torch.nn.ReLU(inplace=True), torch.nn.Dropout(0.2), torch.nn.Linear(128, num_classes))

    def forward(self, x):
        x = self.features(x)
        x = self.pool(x)
        x = self.classifier(x)
        return x

