    return activated * (1 - activated)

def relu(x: numpy.ndarray) -> numpy.ndarray:
    return numpy.maximum(0, x)

def relu_derivative(pre_activation: numpy.ndarray) -> numpy.ndarray:
    derivative = numpy.zeros_like(pre_activation, dtype=numpy.float32)
    for i in range(pre_activation.shape[0]):
        for j in range(pre_activation.shape[1]):
            if pre_activation[i, j] > 0.0:
                derivative[i, j] = 1.0
            else:
                derivative[i, j] = 0.0
    return derivative

def softmax(x: numpy.ndarray) -> numpy.ndarray:
    shifted = x - numpy.max(x, axis=1, keepdims=True)
    exp_values = numpy.exp(shifted)
    return exp_values / numpy.sum(exp_values, axis=1, keepdims=True)

def cross_entropy(probs: numpy.ndarray, targets: numpy.ndarray) -> float:
