from collections import Counter

def build_vocab(texts: typing.List[str], max_vocab=int, min_freq=int):
    counter = collections.Counter()
    for t in texts:
        counter.update(simple_tokenize(t))
    dict = {'<pad>': 0, '<unk>': 1}
    for tok, freq in counter.most_common():
        if freq < min_freq:
            continue
        if tok in dict:
            continue
        dict[tok] = len(dict)
        if len(dict) >= max_vocab:
            break
    dict = {i: s for s, i in dict.items()}
    return (dict, dict)
