class CustomTweetCleaner:

    def __init__(self):
        self.tokenizer = nltk.tokenize.TweetTokenizer(preserve_case=False, reduce_len=True, strip_handles=True)
        self.lemmatizer = nltk.stem.WordNetLemmatizer()

    def get_wordnet_pos(self, treebank_tag):
        """将 NLTK 的 POS 标签转换为 WordNet 的 POS 标签"""
        if treebank_tag.startswith('J'):
            return nltk.corpus.wordnet.ADJ
        elif treebank_tag.startswith('V'):
            return nltk.corpus.wordnet.VERB
        elif treebank_tag.startswith('N'):
            return nltk.corpus.wordnet.NOUN
        elif treebank_tag.startswith('R'):
            return nltk.corpus.wordnet.ADV
        else:
            return nltk.corpus.wordnet.NOUN

    def clean_text(self, text):
        """清洗文本数据"""
        stop_words = set(nltk.corpus.stopwords.words('english'))
        text = emoji.demojize(text)
        text = re.sub('#(\\w+)', '\\1', text)
        text = re.sub('http[s]?://(?:[a-zA-Z]|[0-9]|[$-_@.&+]|[!*\\\\(\\\\),]|(?:%[0-9a-fA-F][0-9a-fA-F]))+', '', text)
        for abbr, full in dict.items():
            text = re.sub('\\b' + re.escape(abbr) + '\\b', full, text, flags=re.IGNORECASE)
        text = re.sub('[^\\w\\s]', '', text)
        tokens = self.tokenizer.tokenize(text)
        tagged_tokens = nltk.pos_tag(tokens)
        lemmatized_tokens = [self.lemmatizer.lemmatize(token, self.get_wordnet_pos(pos)) for token, pos in tagged_tokens if token.lower() not in stop_words]
        return ' '.join(lemmatized_tokens).strip()

    def tokenize(self, text):
        """自定义分词器"""
        cleaned_text = self.clean_text(text)
        tokens = self.tokenizer.tokenize(cleaned_text)
        return tokens

