import string

def calc_upper_ratio(text):
    if len(text) == 0:
        return 0
    upper_count = sum(1 for c in text if c.isupper())
    return upper_count / len(text)

def calc_special_ratio(text):
    if len(text) == 0:
        return 0
    special_count = sum(1 for c in text if c in string.punctuation)
    return special_count / len(text)

processed_train_df['upper_ratio'] = processed_train_df['text'].apply(calc_upper_ratio)
processed_train_df['special_ratio'] = processed_train_df['text'].apply(calc_special_ratio)

